mapper.select:
SELECT COUNT(*) > 0 AS `EXISTS`
FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

SELECT USER_ID, TYPE, NICKNAME
FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}

SELECT KINDERGARTEN_ID, USER_ID, TYPE, ROLE_ID, NICKNAME, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT, UNIX_TIMESTAMP(UPDATED_AT) * 1000 UPDATED_AT
FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

mapper.update:
UPDATE T_RELATIONSHIP
SET ROLE_ID = #{roleId}
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

UPDATE T_RELATIONSHIP
SET NICKNAME = #{nickname}
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

mapper.delete:
DELETE FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}
